import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.CBxkvBm_.js";const g=JSON.parse('{"title":"Graph Rewriting, Pattern Matching & Metaprogramming","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/graph-rewriting.md","filePath":"algorithms/graph-rewriting.md"}'),o={name:"algorithms/graph-rewriting.md"};function n(s,a,l,c,d,p){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="graph-rewriting-pattern-matching-metaprogramming" tabindex="-1">Graph Rewriting, Pattern Matching &amp; Metaprogramming <a class="header-anchor" href="#graph-rewriting-pattern-matching-metaprogramming" aria-label="Permalink to &quot;Graph Rewriting, Pattern Matching &amp; Metaprogramming&quot;">​</a></h1><p><strong>Implementation</strong>: <a href="https://github.com/modelscript/modelscript/tree/main/packages/dsl/src/codegen/rewriting/" target="_blank" rel="noreferrer"><code>packages/dsl/src/codegen/rewriting/</code></a> and <a href="https://github.com/modelscript/modelscript/tree/main/packages/dsl/src/codegen/runtime/" target="_blank" rel="noreferrer"><code>packages/dsl/src/codegen/runtime/</code></a></p><hr><h2 id="_1-triple-graph-grammars-tgg-algebraic-dpo-rewriting" tabindex="-1">1. Triple Graph Grammars (TGG) &amp; Algebraic DPO Rewriting <a class="header-anchor" href="#_1-triple-graph-grammars-tgg-algebraic-dpo-rewriting" aria-label="Permalink to &quot;1. Triple Graph Grammars (TGG) &amp; Algebraic DPO Rewriting&quot;">​</a></h2><h3 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Schürr, A. (1994)</strong>. <em>&quot;Specification of graph translators with triple graph grammars.&quot;</em><br><strong>Graph-Theoretic Concepts in Computer Science (WG &#39;94)</strong>, LNCS 903, pp. 151–163.<br> DOI: <a href="https://doi.org/10.1007/3-540-59071-4_45" target="_blank" rel="noreferrer">10.1007/3-540-59071-4_45</a></li><li><strong>Greenyer, J., &amp; Kindler, E. (2010)</strong>. <em>&quot;Comparing operational execution strategies for triple graph grammars.&quot;</em><br><strong>Software &amp; Systems Modeling</strong>, 9(4), pp. 441–469.<br> DOI: <a href="https://doi.org/10.1007/s10270-009-0140-2" target="_blank" rel="noreferrer">10.1007/s10270-009-0140-2</a></li></ul><h3 id="modelscript-rationale-modifications" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Synchronizes multi-domain engineering languages (e.g. Modelica 1D physics, SysML v2 requirements, STEP CAD geometry) declaratively without fragile point-to-point imperatively paired translators.</p><ul><li><strong>Modifications</strong>: AOT-compiles declarative TGG rule sets into an in-WASM AssemblyScript dispatch kernel (<code>tgg_forward_dispatch</code>, <code>tgg_backward_dispatch</code>); tracks bidirectional correspondences in linear CST memory; achieves $\\mathcal{O}(\\Delta N)$ incremental propagation driven by Salsa invalidations.</li></ul><hr><h2 id="_2-critical-pair-analysis-cpa" tabindex="-1">2. Critical Pair Analysis (CPA) <a class="header-anchor" href="#_2-critical-pair-analysis-cpa" aria-label="Permalink to &quot;2. Critical Pair Analysis (CPA)&quot;">​</a></h2><h3 id="academic-citations-1" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-1" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Knuth, D. E., &amp; Bendix, P. B. (1970)</strong>. <em>&quot;Simple word problems in universal algebras.&quot;</em><br><strong>Computational Problems in Abstract Algebra</strong>, pp. 263–297. Pergamon Press.</li><li><strong>Ehrig, H., Ehrig, K., de Lara, J., Taentzer, G., Varró, D., &amp; Varró, G. (2005)</strong>. <em>&quot;Termination and confluence of graph transformation systems.&quot;</em><br><strong>Formal Methods in Software and Systems Modeling</strong>, LNCS 3440, pp. 180–195. DOI: <a href="https://doi.org/10.1007/978-3-540-31847-7_11" target="_blank" rel="noreferrer">10.1007/978-3-540-31847-7_11</a></li><li><strong>Heckel, R., &amp; Taentzer, G. (2020)</strong>. <em>Graph Transformation for Software Engineers: Formal Foundation and Industrial Applications</em>.<br><strong>Springer</strong>. DOI: <a href="https://doi.org/10.1007/978-3-030-43969-9" target="_blank" rel="noreferrer">10.1007/978-3-030-43969-9</a></li></ul><h3 id="modelscript-rationale-modifications-1" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-1" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>In polyglot workflows, multiple rules may compete to transform the same AST elements. CPA statically detects all critical pairs (conflicting rule overlaps, target collisions, and circular translation loops) at compile time.</p><ul><li><strong>Modifications</strong>: Tailored for heterogeneous polyglot metamodels; emits structured diagnostics with source ranges and rule conflict identifiers directly to the LSP and CLI.</li></ul><hr><h2 id="_3-worst-case-optimal-joins-wcoj-leapfrog-triejoin" tabindex="-1">3. Worst-Case Optimal Joins (WCOJ / Leapfrog Triejoin) <a class="header-anchor" href="#_3-worst-case-optimal-joins-wcoj-leapfrog-triejoin" aria-label="Permalink to &quot;3. Worst-Case Optimal Joins (WCOJ / Leapfrog Triejoin)&quot;">​</a></h2><h3 id="academic-citations-2" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-2" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Ngo, H. Q., Porat, E., Ré, C., &amp; Rudra, A. (2012)</strong>. <em>&quot;Worst-case optimal join algorithms.&quot;</em><br><strong>ACM PODS &#39;12</strong>, pp. 37–48. DOI: <a href="https://doi.org/10.1145/2213556.2213565" target="_blank" rel="noreferrer">10.1145/2213556.2213565</a></li><li><strong>Veldhuizen, T. L. (2014)</strong>. <em>&quot;Leapfrog Triejoin: A simple, worst-case optimal join algorithm.&quot;</em><br><strong>ICDT &#39;14</strong>, pp. 96–106. DOI: <a href="https://doi.org/10.4230/LIPIcs.ICDT.2014.96" target="_blank" rel="noreferrer">10.4230/LIPIcs.ICDT.2014.96</a></li><li><strong>Atserias, A., Grohe, M., &amp; Marx, D. (2008)</strong>. <em>&quot;Size bounds and query plans for relational joins.&quot;</em><br><strong>IEEE FOCS &#39;08</strong>, pp. 739–748. (The AGM Bound)</li></ul><h3 id="modelscript-rationale-modifications-2" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-2" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Traditional binary relational joins suffer from exponential intermediate result explosions on cyclic subgraphs (e.g. triangle topologies between ports, connectors, and component definitions). WCOJ guarantees runtime strictly bounded by the Atserias-Grohe-Marx (AGM) bound, achieving $\\mathcal{O}(N^{3/2})$ for triangle queries rather than $\\mathcal{O}(N^2)$.</p><ul><li><strong>Modifications</strong>: Formulates Leapfrog Triejoin iteration orders using descending vertex degree heuristics; emits execution plans directly into the AOT WebAssembly compilation engine.</li></ul><hr><h2 id="_4-zero-gc-e-graphs-equality-saturation" tabindex="-1">4. Zero-GC E-Graphs &amp; Equality Saturation <a class="header-anchor" href="#_4-zero-gc-e-graphs-equality-saturation" aria-label="Permalink to &quot;4. Zero-GC E-Graphs &amp; Equality Saturation&quot;">​</a></h2><h3 id="academic-citations-3" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-3" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Nelson, G., &amp; Oppen, D. C. (1980)</strong>. <em>&quot;Fast decision procedures based on congruence closure.&quot;</em><br><strong>Journal of the ACM</strong>, 27(2), pp. 356–364. DOI: <a href="https://doi.org/10.1145/322186.322198" target="_blank" rel="noreferrer">10.1145/322186.322198</a></li><li><strong>Tate, R., Stepp, M., Tatlock, Z., &amp; Lerner, S. (2009)</strong>. <em>&quot;Equality saturation: A new approach to optimization.&quot;</em><br><strong>ACM POPL &#39;09</strong>, pp. 264–276. DOI: <a href="https://doi.org/10.1145/1480881.1480915" target="_blank" rel="noreferrer">10.1145/1480881.1480915</a></li><li><strong>Willsey, M., et al. (2021)</strong>. <em>&quot;egg: Fast and extensible equality saturation.&quot;</em><br><strong>ACM POPL &#39;21</strong>, pp. 1–29. DOI: <a href="https://doi.org/10.1145/3434304" target="_blank" rel="noreferrer">10.1145/3434304</a></li></ul><h3 id="modelscript-rationale-modifications-3" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-3" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Avoids destructive phase-ordering in symbolic equation simplification. An E-Graph maintains exponential equivalence classes of mathematically equal expressions simultaneously, extracting the globally minimal expression before numerical simulation.</p><ul><li><strong>Modifications</strong>: WebAssembly linear memory allocation with zero GC; 32-bit Union-Find with two-pass path compression; fixed power-of-two open-addressing hash table (<code>HASH_MASK = 65535</code>) for $\\mathcal{O}(1)$ deduplication.</li></ul><hr><h2 id="_5-graph-structured-stack-gss-glr-parsing" tabindex="-1">5. Graph-Structured Stack (GSS) GLR Parsing <a class="header-anchor" href="#_5-graph-structured-stack-gss-glr-parsing" aria-label="Permalink to &quot;5. Graph-Structured Stack (GSS) GLR Parsing&quot;">​</a></h2><h3 id="academic-citations-4" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-4" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Tomita, M. (1985)</strong>. <em>Efficient Parsing for Natural Language: A Fast Generalized LR Algorithm</em>.<br><strong>Kluwer Academic Publishers</strong>. DOI: <a href="https://doi.org/10.1007/978-1-4613-2621-2" target="_blank" rel="noreferrer">10.1007/978-1-4613-2621-2</a></li><li><strong>Scott, E., &amp; Johnstone, A. (2006)</strong>. <em>&quot;Right Numerate Generalized LR Parsers.&quot;</em><br><strong>ACM TOPLAS</strong>, 28(4), pp. 577–618. DOI: <a href="https://doi.org/10.1145/1176894.1176896" target="_blank" rel="noreferrer">10.1145/1176894.1176896</a></li><li><strong>McPeak, S., &amp; Necula, G. C. (2004)</strong>. <em>&quot;Elkhound: A fast, practical GLR parser generator.&quot;</em><br><strong>Compiler Construction (CC 2004)</strong>, LNCS 2985, pp. 73–88. DOI: <a href="https://doi.org/10.1007/978-3-540-24723-4_6" target="_blank" rel="noreferrer">10.1007/978-3-540-24723-4_6</a></li></ul><h3 id="modelscript-rationale-modifications-4" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-4" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Handles ambiguous and non-deterministic engineering grammars (such as expression vs. component declaration ambiguities in Modelica and SysML v2) by splitting and merging parse paths via the GSS without backtracking.</p><ul><li><strong>Modifications</strong>: Active stack heads reside in contiguous unmanaged buffers (<code>t_activeHeads</code>) with power-of-two hash probing for $\\mathcal{O}(1)$ stack head merging in WebAssembly.</li></ul><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>Raw source code parsed by the <a href="./../architecture/glr-parser.html"><code>WASM GLR Parser</code></a>.</li><li>Polyglot synchronization rules authored in <code>@modelscript/dsl</code>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Rewritten expressions feed directly into <a href="./../architecture/dae-arena.html"><code>DAEBuilder</code></a>.</li><li>TGG synchronizations feed bidirectional updates between SysML v2 and Modelica.</li></ul></li></ul>',40)])])}const h=e(o,[["render",n]]);export{g as __pageData,h as default};
